parts.solution:
def parse_line(line: str) -> Entry:
    parts = line.split()
    if len(parts) != 5:
        raise ValueError(f"expected 5 fields, got {len(parts)}: {line!r}")
    timestamp, method, path, status, duration = parts
    if not duration.endswith("ms"):
        raise ValueError(f"duration must end in 'ms': {duration!r}")
    try:
        return Entry(timestamp, method, path, int(status), int(duration[:-2]))
    except ValueError as e:
        raise ValueError(f"bad number in line {line!r}") from e

from dataclasses import dataclass


@dataclass
class ReadStats:
    skipped: int = 0


def read_entries(path, stats=None):
    stats = stats if stats is not None else ReadStats()
    with open(path, encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            try:
                yield parse_line(line)
            except ValueError:
                stats.skipped += 1

