export function useDebouncedValue(value, delayMs) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(id);
  }, [value, delayMs]);
  return debounced;
}

export function useSearch(query) {
  const [state, setState] = useState({ results: [], loading: false, error: null });
  useEffect(() => {
    if (!query) {
      setState({ results: [], loading: false, error: null });
      return;
    }
    const controller = new AbortController();
    setState((s) => ({ ...s, loading: true, error: null }));
    fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal: controller.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((results) => setState({ results, loading: false, error: null }))
      .catch((error) => {
        if (error.name === 'AbortError') return;
        setState({ results: [], loading: false, error });
      });
    return () => controller.abort();
  }, [query]);
  return state;
}

export function ProductSearch() {
  const [text, setText] = useState('');
  const query = useDebouncedValue(text.trim(), 300);
  const { results, loading, error } = useSearch(query);

  let body;
  if (error) body = <p role="alert">Search failed: {error.message}</p>;
  else if (loading) body = <p>Searching...</p>;
  else if (query && results.length === 0) body = <p>No products match "{query}".</p>;
  else body = (
    <ul>
      {results.map((p) => <li key={p.id}>{p.name}</li>)}
    </ul>
  );

  return (
    <div>
      <input
        aria-label="Search products"
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      {body}
    </div>
  );
}
